INSERT INTO "knowledge_chunks" ("chunk_id", "document_id", "hierarchical_level", "section_type", "content", "content_tsv", "embedding", "parent_chunk_id", "child_chunk_ids", "importance_score", "authority_score", "recency_score", "created_at") VALUES ('6f2010cd-168a-4d04-9527-c1da642414c9', 'eaecb80b-27fa-47c0-ba55-ac541541cb21', 'section', 'other', '{''raw_text'': ''INDIAN LEGAL DOCTRINES & PRINCIPLES COMPENDIUM\nPage 1 of 1\nESSENTIAL INDIAN LEGAL DOCTRINES & PRINCIPLES\n1. Natural Justice (Audi Alteram Partem & Nemo Judex In Causa Sua): No person shall be condemned unheard, and no person shall be a judge in their own cause.\n2. Res Judicata (Section 11 CPC): A matter once finally adjudicated by a competent court cannot be re-agitated between the same parties.\n3. Basic Structure Doctrine: Constitutional amendments violating fundamental core framework are void (Kesavananda Bharati v. State of Kerala).\n4. Doctrine of Proportionality: Administrative & legislative measures restricting rights must be strictly proportionate to legitimate state objectives.\n5. Promissory Estoppel: State or individual cannot backtrack on promises where the other party acted upon them to their detriment.\nOfficial Indian Legal Database - Phase 1 Core Collection''}', NULL, '[0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001,